def extended_gcd_algorithm(a, b):
    r_prev, r_curr = a, b
    s_prev, s_curr = 1, 0
    t_prev, t_curr = 0, 1
    while r_curr:
        q = r_prev // r_curr
        r_prev, r_curr = r_curr, r_prev - q * r_curr
        s_prev, s_curr = s_curr, s_prev - q * s_curr
        t_prev, t_curr = t_curr, t_prev - q * t_curr
    return r_prev, s_prev


def compute_binomial_coeffs(n, M):
    C = [0] * (n + 1)
    C[n] = 1
    for k in range(n - 1, -1, -1):
        C[k] = (C[k + 1] * (k + 1)) % M
        if not C[k]:
            break
    return C


def main_calculation(n, M):
    K = [[[1]]]
    for i in range(n - 1):
        prev_layer = K[i]
        size_prev = len(prev_layer)
        new_layer = [[0] * (i + 2) for _ in range(size_prev + i + 1)]
        K.append(new_layer)
        for j, row in enumerate(prev_layer):
            for k, val in enumerate(row):
                for h in range(i + 1):
                    new_layer[j + h][k] = (new_layer[j + h][k] + val) % M
                new_layer[j + i + 1][i + 1] = (new_layer[j + i + 1][i + 1] + val) % M

    C = compute_binomial_coeffs(n, M)
