import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split(" ");
        int n = Integer.parseInt(input[0]);
        int m = Integer.parseInt(input[1]);
        System.out.println(mainCalculation(n, m));
    }

    static int mainCalculation(int n, int M) {
        List<List<int[]>> K = new ArrayList<>();
        List<int[]> firstLayer = new ArrayList<>();
        firstLayer.add(new int[]{1});
        K.add(firstLayer);
        for (int i = 0; i < n - 1; i++) {
            List<int[]> prevLayer = K.get(i);
            int sizePrev = prevLayer.size();
            List<int[]> newLayer = new ArrayList<>();
            for (int j = 0; j < sizePrev + i + 1; j++) {
                newLayer.add(new int[i + 2]);
            }
            K.add(newLayer);
            for (int j = 0; j < sizePrev; j++) {
                int[] row = prevLayer.get(j);
                for (int k = 0; k < row.length; k++) {
                    for (int h = 0; h < i + 1; h++) {
                        newLayer.get(j + h)[k] = (newLayer.get(j + h)[k] + row[k]) % M;
                    }
                    newLayer.get(j + i + 1)[i + 1] = (newLayer.get(j + i + 1)[i + 1] + row[k]) % M;
                }
            }
        }
        int[] C = computeBinomialCoeffs(n, M);
        long totalSum = 0;
        for (int i = 1; i < n; i++) {
            List<int[]> layer = K.get(i);
            int ni = layer.size();
            int mi = layer.get(0).length;
            int[][] S = new int[ni][mi];
            for (int j = 0; j < ni; j++) {
                System.arraycopy(layer.get(j), 0, S[j], 0, mi);
            }
            for (int j = 0; j < ni; j++) {
                for (int k = mi - 2; k >= 0; k--) {
                    S[j][k] = (S[j][k] + S[j][k + 1]) % M;
                }
            }
            for (int j = 1; j < ni; j++) {
                for (int k = 0; k < mi; k++) {
                    S[j][k] = (S[j][k] + S[j - 1][k]) % M;
                }
            }
            long sumValue = 0;
            for (int j = 1; j < ni; j++) {
                for (int k = 0; k < mi - 1; k++) {
                    long temp = ((long) layer.get(j)[k] * S[j - 1][k + 1]) % M;
                    sumValue = (sumValue + temp) % M;
                }
            }
            int c = C[i + 1];
            sumValue = (sumValue * c) % M;
            totalSum = (totalSum + sumValue) % M;
        }
        return (int) totalSum;
    }

    static int[] computeBinomialCoeffs(int n, int M) {
        int[] C = new int[n + 1];
        C[n] = 1;
        for (int k = n - 1; k >= 0; k--) {
            C[k] = (int) (((long) C[k + 1] * (k + 1)) % M);
            if (C[k] == 0) {
                break;
            }
        }
        return C;
    }
}
